def log_call(fn):
    def wrapper():
        print("before")
        fn()
    return wrapper

@log_call
def run():
    print("run")

run()

class Timer:
    def __enter__(self):
        print("start")
        return self

    def __exit__(self, exc_type, exc, tb):
        print("end")

with Timer():
    print("work")

